story += [tbl([[P(v,'thx') for v in st[0]]]+[[P(v,'smx') for v in row] for row in st[1:]],[48*mm,CW-48*mm]),P('Hardware safety notes','h2x'),P('MAX30102 is an optical heart-rate/pulse-oximeter sensor; breakout boards differ in regulator and logic-level design, so check the exact board before wiring. MLX90614 is a non-contact infrared surface/object thermometer; it is not a direct core-body measurement. Raspberry Pi GPIO is 3.3 V logic. Stop motors during readings, isolate motor supply current from sensor rails, verify L298N limits, and use official component documentation [9-12].','bx'),PageBreak()]
story += [P('8. Evaluation Metrics and Results','h1x'),P('8.1 Metric definitions','h2x'),P('Accuracy is correct predictions divided by all test images. Per-class precision = TP/(TP+FP), recall = TP/(TP+FN), and F1 = 2 x precision x recall / (precision + recall). Macro-F1 is the unweighted mean of class F1. Balanced accuracy is the mean recall across classes. Cross-entropy loss penalizes low probability assigned to the correct class. The confusion matrix records true versus predicted labels.'),P('These metrics measure the skin image classifier only. They do not assess LLM answer quality, triage rules, sensor measurement accuracy, or whole-robot performance.','callx'),P('8.2 Per-class test results','h2x')]
